<style>#scheduler-calendar{background:#fff;padding:20px;border-radius:8px;-webkit-box-shadow:0 0 10px rgba(0,0,0,.1);box-shadow:0 0 10px rgba(0,0,0,.1);margin-bottom:30px}#scheduler-calendar .fc-header-toolbar{margin-bottom:1.5em}#scheduler-calendar .fc-toolbar-title{font-size:1.25em;font-weight:600}#scheduler-calendar .fc-button{background-color:#3bb4e5;border-color:#3bb4e5}#scheduler-calendar .fc-button:hover{background-color:#1c9dd1;border-color:#1c9dd1}#scheduler-calendar .fc-button:focus{-webkit-box-shadow:0 0 0 .2rem rgba(59,180,229,.5);box-shadow:0 0 0 .2rem rgba(59,180,229,.5)}#scheduler-calendar .fc-button-active{background-color:#167ba4!important;border-color:#167ba4!important}#scheduler-calendar .fc-daygrid-day-events{min-height:5em}#scheduler-calendar .fc-bg-event{opacity:1;padding:10px;z-index:10}#scheduler-calendar .fc-bg-event .uploaded-schedule{text-align:center}#scheduler-calendar .fc-bg-event .uploaded-schedule i{color:red;font-size:80px}#scheduler-calendar .fc-bg-event .uploaded-schedule-actions{display:-webkit-box;display:-webkit-flex;display:-moz-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-webkit-align-items:center;-moz-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-webkit-justify-content:center;-moz-box-pack:center;-ms-flex-pack:center;justify-content:center;width:100%;gap:10px;margin-top:5px}#scheduler_form .shift-card,#scheduler_view .shift-card{-webkit-transition:all .3s ease;-moz-transition:all .3s ease;transition:all .3s ease}#scheduler_form .staff-row,#scheduler_view .staff-row{display:-webkit-box;display:-webkit-flex;display:-moz-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-webkit-align-items:center;-moz-box-align:center;-ms-flex-align:center;align-items:center;padding:10px;border-bottom:1px solid #f0f0f0}#scheduler_form .staff-row:last-child,#scheduler_view .staff-row:last-child{border-bottom:none}#scheduler_form .staff-avatar,#scheduler_view .staff-avatar{width:60px;height:60px;border-radius:50%;background-color:#eee;margin-right:15px;display:-webkit-box;display:-webkit-flex;display:-moz-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-webkit-align-items:center;-moz-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-webkit-justify-content:center;-moz-box-pack:center;-ms-flex-pack:center;justify-content:center;overflow:hidden}#scheduler_form .staff-avatar img,#scheduler_view .staff-avatar img{width:100%;height:100%;-o-object-fit:cover;object-fit:cover}#scheduler_form .staff-info,#scheduler_view .staff-info{-webkit-box-flex:1;-webkit-flex-grow:1;-moz-box-flex:1;-ms-flex-positive:1;flex-grow:1}#scheduler_form .staff-name,#scheduler_view .staff-name{font-weight:600;font-size:1.1rem}#scheduler_form .staff-position,#scheduler_view .staff-position{color:#007bff;font-weight:700}#scheduler_form .staff-actions,#scheduler_view .staff-actions{display:-webkit-box;display:-webkit-flex;display:-moz-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-webkit-align-items:center;-moz-box-align:center;-ms-flex-align:center;align-items:center}#scheduler_form .btn-edit-staff,#scheduler_view .btn-edit-staff{color:#999;cursor:pointer;font-weight:600}#scheduler_form .btn-edit-staff i,#scheduler_view .btn-edit-staff i{margin-right:5px}#scheduler_form .shift-header-content h5,#scheduler_view .shift-header-content h5{font-weight:600}#scheduler_view .staff-actions{display:none}</style>